import{C as i,c as l,o as d,ag as e,j as r,G as s}from"./chunks/framework.S-Qvb3wi.js";const o="/img/png/frontend/HTML/4.png",c="/img/png/frontend/HTML/5.png",p="/img/png/frontend/HTML/6.png",h="/img/png/frontend/HTML/7.png",g="/img/png/frontend/HTML/8.png",x={style:{display:"flex","flex-direction":"column","align-items":"center"}},_=JSON.parse('{"title":"基本概念","titleTemplate":"前端基础","description":"基本概念","frontmatter":{"title":"基本概念","titleTemplate":"前端基础","description":"基本概念","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":{"text":"初体验","link":"/frontend/HTML/HTML_2"}},"headers":[],"relativePath":"frontend/HTML/HTML_1.md","filePath":"frontend/HTML/HTML_1.md","lastUpdated":null}'),b={name:"frontend/HTML/HTML_1.md"},u=Object.assign(b,{setup(m){const a=[{src:"/img/png/frontend/HTML/1.png",alt:"京东官网"},{src:"/img/png/frontend/HTML/2.png",alt:"网页示例2"},{src:"/img/png/frontend/HTML/3.png",alt:"网页示例3"}];return(y,t)=>{const n=i("Carousel");return d(),l("div",null,[t[1]||(t[1]=e('<h1 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h1><h2 id="认识网页" tabindex="-1">认识网页 <a class="header-anchor" href="#认识网页" aria-label="Permalink to &quot;认识网页&quot;">​</a></h2><p>网页是由<span class="marker-evy">文字、图片、视频、音频、超链接</span>等组成，为用户提供信息的交互界面。网页的本质就是前端程序员写的代码，然后通过浏览器进行解析和渲染，最后转换成用户的眼中的页面。</p><br>',4)),r("div",x,[s(n,{images:a,width:"600px",height:"400px","border-radius":"25px",duration:12}),t[0]||(t[0]=r("p",{style:{color:"gray","font-size":"0.9em","margin-top":"10px"}},"生活中的各种网页",-1))]),t[2]||(t[2]=e('<h2 id="浏览器和渲染引擎" tabindex="-1">浏览器和渲染引擎 <a class="header-anchor" href="#浏览器和渲染引擎" aria-label="Permalink to &quot;浏览器和渲染引擎&quot;">​</a></h2><h3 id="浏览器" tabindex="-1">浏览器 <a class="header-anchor" href="#浏览器" aria-label="Permalink to &quot;浏览器&quot;">​</a></h3><p>浏览器是网页显示、运行的平台 ，是前端开发必备的工具。</p><p>常见的浏览器有：<s>IE 浏览器（Internet Explorer）</s>、Safari 浏览器、谷歌浏览器（Chrome）、火狐浏览器（Firefox）、欧朋浏览器（Opera）</p><br><div style="display:flex;justify-content:center;align-items:center;gap:20px;flex-wrap:wrap;"><img src="'+o+'" width="100" height="100" style="object-fit:contain;border-radius:10px;"><img src="'+c+'" width="85" height="85" style="object-fit:contain;border-radius:10px;"><img src="'+p+'" width="100" height="100" style="object-fit:contain;border-radius:10px;"><img src="'+h+'" width="85" height="85" style="object-fit:contain;border-radius:10px;"><img src="'+g+'" width="100" height="100" style="object-fit:contain;border-radius:10px;"></div><p style="color:gray;font-size:0.9em;margin-top:10px;text-align:center;">常见的浏览器</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>截至 2022 年 6 月 15 日，微软已宣布对 Internet Explorer 停止维护。（详细信息可参考<a href="https://learn.microsoft.com/zh-cn/lifecycle/announcements/internet-explorer-11-end-of-support-windows-10" target="_blank" rel="noreferrer">微软官方公告</a>）</p></div><h3 id="渲染引擎" tabindex="-1">渲染引擎 <a class="header-anchor" href="#渲染引擎" aria-label="Permalink to &quot;渲染引擎&quot;">​</a></h3><p>渲染引擎，即浏览器内核，是浏览器中专门对代码进行解析渲染的部分。浏览器出品的公司不同，内在的渲染引擎也有所不同：</p><div style="display:flex;justify-content:center;"><table tabindex="0"><thead><tr><th style="text-align:center;">浏览器</th><th style="text-align:center;">内核</th><th style="text-align:center;">备注</th></tr></thead><tbody><tr><td style="text-align:center;">IE</td><td style="text-align:center;">Trident</td><td style="text-align:center;">IE、猎豹安全、360极速浏览器、百度浏览器</td></tr><tr><td style="text-align:center;">FireFox</td><td style="text-align:center;">Gecko</td><td style="text-align:center;">火狐浏览器内核</td></tr><tr><td style="text-align:center;">Safari</td><td style="text-align:center;">Webkit</td><td style="text-align:center;">苹果浏览器内核</td></tr><tr><td style="text-align:center;">Chrome / Opera</td><td style="text-align:center;">Blink</td><td style="text-align:center;">Blink 其实是 Webkit 的分支</td></tr></tbody></table></div><p>渲染引擎不同，导致解析相同代码时的速度、性能、效果也不同的。目前而言，谷歌浏览器的渲染引擎速度快、性能高、效果好，所以更吸引用户的喜爱（推荐）。</p><h2 id="web-标准" tabindex="-1">Web 标准 <a class="header-anchor" href="#web-标准" aria-label="Permalink to &quot;Web 标准&quot;">​</a></h2><h3 id="为什么需要-web-标准" tabindex="-1">为什么需要 Web 标准？ <a class="header-anchor" href="#为什么需要-web-标准" aria-label="Permalink to &quot;为什么需要 Web 标准？&quot;">​</a></h3><p>不同的浏览器的渲染引擎不同，对于相同代码解析的效果会存在差异；换言之，如果用户想看一个网页，用不同浏览器打开效果不同，就会导致用户体验极差。此时，WEB 标准就应运而生。</p><p><b>WEB 标准</b>：让不同的浏览器按照相同的标准显示结果，让展示的效果统一！</p><h3 id="web-标准的构成" tabindex="-1">Web 标准的构成 <a class="header-anchor" href="#web-标准的构成" aria-label="Permalink to &quot;Web 标准的构成&quot;">​</a></h3><p>WEB 标准分为三个组成部分：</p><div style="display:flex;justify-content:center;"><table tabindex="0"><thead><tr><th style="text-align:center;">组成</th><th style="text-align:center;">语言</th><th style="text-align:center;">说明</th></tr></thead><tbody><tr><td style="text-align:center;">结构</td><td style="text-align:center;">HTML</td><td style="text-align:center;">页面元素和内容</td></tr><tr><td style="text-align:center;">样式</td><td style="text-align:center;">CSS</td><td style="text-align:center;">网页元素的外观和位置等页面样式</td></tr><tr><td style="text-align:center;">行为</td><td style="text-align:center;">JavaScript</td><td style="text-align:center;">网页模型的定义和页面交互</td></tr></tbody></table></div><p>WEB 标准要求页面实现：结构、表现、行为三者分离。</p>',20))])}}});export{_ as __pageData,u as default};
